# Use clean per-base-component algorithm, with maximal rectangles when one component holds several symbols.
def transform(grid):
 from collections import Counter
 g=grid; H=len(g); W=len(g[0])
 blues={(r,c) for r in range(H) for c in range(W) if g[r][c]==1}
 symbols=[]
 while blues:
  seed=blues.pop(); stack=[seed]; cells=[seed]
  while stack:
   r,c=stack.pop()
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     p=(r+dr,c+dc)
     if p in blues: blues.remove(p); stack.append(p); cells.append(p)
  adj=[g[r+dr][c+dc] for r,c in cells for dr in (-1,0,1) for dc in (-1,0,1)
       if 0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]!=1]
  base=Counter(adj).most_common(1)[0][0]
  rs=[r for r,c in cells]; cs=[c for r,c in cells]
  special=[(r,c,g[r][c]) for r in range(min(rs),max(rs)+1) for c in range(min(cs),max(cs)+1) if g[r][c] not in (1,base)]
  out=special[0][2] if special and special[0][2]!=3 else (7 if special else 3)
  symbols.append((cells,base,out,special))
 result=[[7]*W for _ in range(H)]
 # Find monochromatic connected regions, treating blue and symbol-center cells as obstacles initially.
 seen=set()
 for r in range(H):
  for c in range(W):
   if g[r][c]==1 or (r,c) in seen: continue
   color=g[r][c]; stack=[(r,c)]; seen.add((r,c)); comp=[]
   while stack:
    a,b=stack.pop(); comp.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=a+da,b+db
     if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==color:
      seen.add((x,y)); stack.append((x,y))
   matches=[s for s in symbols if s[1]==color and any(abs(a-x)+abs(b-y)==1 for x,y in s[0] for a,b in comp)]
   if len(matches)<=1:
    val=matches[0][2] if matches else 7
    for p in comp: result[p[0]][p[1]]=val
   else:
    # A demo may join rectangular same-colored regions. Recover each symbol's maximal rectangle.
    covered=set()
    for cells,base,val,special in matches:
     pts=cells+[(a,b) for a,b,v in special]
     r0=min(a for a,b in pts); r1=max(a for a,b in pts); c0=min(b for a,b in pts); c1=max(b for a,b in pts)
     best=None
     for top in range(r0+1):
      for bottom in range(r1,H):
       for left in range(c0+1):
        for right in range(c1,W):
         area=(bottom-top+1)*(right-left+1)
         if best and area<=best[0]: continue
         if all(g[a][b] in (base,1) or (a,b) in covered for a in range(top,bottom+1) for b in range(left,right+1)):
          best=(area,top,bottom,left,right)
     if best:
      _,top,bottom,left,right=best
      for a in range(top,bottom+1):
       for b in range(left,right+1): result[a][b]=val; covered.add((a,b))
 for cells,base,val,special in symbols:
  for r,c in cells: result[r][c]=val
  for r,c,v in special: result[r][c]=val
 return [list(row) for row in zip(*result)]
